import {fields,normalize,phoneLink,safeUrl,dedupeKey,instagramUrl} from './core.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',columns:'M3 3h18v18H3z M9 3v18 M15 3v18',calendar:'M3 5h18v16H3z M16 3v4 M8 3v4 M3 11h18',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',upload:'M12 16V4 M7 9l5-5 5 5 M4 16v5h16v-5',plus:'M12 5v14 M5 12h14',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',close:'M6 6l12 12 M18 6L6 18',map:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',instagram:'M7 3h10a4 4 0 0 1 4 4v10a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4V7a4 4 0 0 1 4-4 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M17 7h.01',whatsapp:'M20 11.5a8 8 0 0 1-12 7L3 20l1.5-5A8 8 0 1 1 20 11.5 M8 7c0 4 2 6 6 7l2-2-3-1-1 1-2-2 1-1-1-3z',edit:'M16 3l5 5-12 12H4v-5z M14 5l5 5',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1 6.2-5.5-2.9-5.5 2.9 1-6.2L3 9.6l6.2-.9z',arrow:'M5 12h14 M14 7l5 5-5 5',check:'M5 12l4 4L19 6'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.users}"/></svg>`;
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
const stages={novo:'Novo lead',contactado:'Contatado',proposta:'Proposta enviada',negociacao:'Em negociação',fechado:'Fechado',perdido:'Sem interesse'};
let leads=[],view='leads',editing=null,workbook=null,mapping={},importRows=[],toastTimer;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500)}
function persist(next){try{localStorage.setItem('prospect-leads-v1',JSON.stringify(next));leads=next;render();return true}catch{toast('Não foi possível salvar. Baixe um backup e libere espaço no navegador.');return false}}
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const fmtDate=d=>d?new Date(d+'T12:00:00').toLocaleDateString('pt-BR'):'Sem data';
function link(url,label,type){return `<a class="icon-btn ${type}" ${url?`href="${esc(url)}" target="_blank" rel="noopener noreferrer"`:'aria-disabled="true" tabindex="-1"'} aria-label="${label}" title="${url?label:label+' indisponível'}">${icon(type)}</a>`}
function actions(l){return `<div class="row-actions">${link(safeUrl(l.maps)||'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent([l.name,l.address,l.city].filter(Boolean).join(' ')),'Ver no mapa','map')}${link(instagramUrl(l.instagram),'Abrir Instagram','instagram')}${link(phoneLink(l.phone),'Conversar no WhatsApp','whatsapp')}<button class="icon-btn" data-edit="${l.id}" title="Editar lead" aria-label="Editar ${esc(l.name)}">${icon('edit')}</button></div>`}
function options(value){return Object.entries(stages).map(([k,v])=>`<option value="${k}" ${value===k?'selected':''}>${v}</option>`).join('')}
$('#status-filter').innerHTML='<option value="">Todas as etapas</option>'+options();$('#edit-status').innerHTML=options();
function filtered(){let list=leads.filter(l=>(!$('#status-filter').value||l.status===$('#status-filter').value)&&(!$('#district-filter').value||l.district===$('#district-filter').value)&&normalize([l.name,l.district,l.city,l.phone,l.category,l.email].join(' ')).includes(normalize($('#search').value)));const sort=$('#sort').value;return list.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name,'pt-BR'):sort==='rating'?(+b.rating||0)-(+a.rating||0):sort==='followup'?(a.followup||'9999').localeCompare(b.followup||'9999'):(+b.reviews||0)-(+a.reviews||0))}
function render(){const list=filtered(),district=$('#district-filter').value;$('#district-filter').innerHTML='<option value="">Todos os bairros</option>'+[...new Set(leads.map(l=>l.district).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR')).map(d=>`<option ${d===district?'selected':''}>${esc(d)}</option>`).join('');$('#nav-count').textContent=leads.length;$('#stats').innerHTML=[['users','Leads na sua base',leads.length,'oportunidades'],['arrow','Conversas iniciadas',leads.filter(l=>!['novo','perdido'].includes(l.status)).length,'conexões'],['columns','Propostas em aberto',leads.filter(l=>['proposta','negociacao'].includes(l.status)).length,'em andamento'],['check','Negócios fechados',leads.filter(l=>l.status==='fechado').length,'novos clientes']].map(([i,label,n,small])=>`<div class="stat"><div class="stat-label">${icon(i)}${label}</div><div class="stat-value"><strong>${n.toString().padStart(2,'0')}</strong><small>${small}</small></div></div>`).join('');$('#filtered-count').textContent=list.length;$('#result-summary').textContent=`${list.length} de ${leads.length} leads`;
if(view==='pipeline'){$('#results').innerHTML=`<div class="kanban">${Object.entries(stages).map(([s,label])=>`<div class="kanban-col"><h3>${label} · ${list.filter(l=>l.status===s).length}</h3>${list.filter(l=>l.status===s).map(l=>`<article class="kanban-card"><button data-edit="${l.id}">${esc(l.name)}</button><div class="sub">${esc(l.district||l.city)}</div><select data-stage="${l.id}" aria-label="Etapa de ${esc(l.name)}">${options(s)}</select></article>`).join('')}</div>`).join('')}</div>`;return}
if(view==='tasks'){const tasks=list.filter(l=>l.followup&&!['fechado','perdido'].includes(l.status)).sort((a,b)=>a.followup.localeCompare(b.followup));$('#results').innerHTML=tasks.length?tasks.map(l=>`<div class="task"><time>${fmtDate(l.followup)}${l.followup<today()?' · Atrasado':l.followup===today()?' · Hoje':''}</time><button data-edit="${l.id}">${esc(l.name)}<div class="sub">${esc(l.notes||stages[l.status])}</div></button><div style="margin-left:auto">${actions(l)}</div></div>`).join(''):'<div class="empty"><h3>Uma agenda pronta para novas conversas</h3>Abra um lead e defina a data do próximo contato.</div>';return}
$('#results').innerHTML=list.length?`<div class="table-wrap"><table><thead><tr><th>Negócio</th><th>Localização</th><th>Google</th><th>Etapa</th><th>Conectar</th></tr></thead><tbody>${list.map(l=>`<tr><td><div class="lead-name"><span class="avatar">${esc(l.name.split(' ').filter(Boolean).slice(0,2).map(n=>n[0]).join('').toUpperCase())}</span><div><button data-edit="${l.id}">${esc(l.name)}</button><div class="sub">${esc(l.category||'Categoria não informada')}</div></div></div></td><td>${esc(l.district||'—')}<div class="sub">${esc(l.city||'Cidade não informada')}</div></td><td><div class="rating">${icon('star')}${l.rating?esc(String(l.rating).replace('.',',')):'—'}<small>${l.reviews?'('+Number(l.reviews).toLocaleString('pt-BR')+')':''}</small></div></td><td><span class="badge ${l.status}">${stages[l.status]}</span>${l.followup?`<div class="sub">${fmtDate(l.followup)}</div>`:''}</td><td>${actions(l)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>'+ (leads.length?'Nenhum lead encontrado':'Sua próxima oportunidade está aqui')+'</h3>'+(leads.length?'Ajuste a busca ou os filtros.':'Importe uma planilha ou adicione seu primeiro lead.')+'</div>'}
['search','status-filter','district-filter','sort'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',render));
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n===b));const title={leads:['Meus leads','Sua lista de oportunidades','Um bom site pode ser o próximo passo desses negócios.'],pipeline:['Funil de vendas','Do primeiro olá ao negócio fechado','Acompanhe cada oportunidade e atualize a etapa.'],tasks:['Próximos contatos','Mantenha as conversas em movimento','Seus retornos agendados, em ordem de data.']}[view];$('#breadcrumb').textContent=title[0];$('#list-title').innerHTML=title[1]+' <span id="filtered-count"></span>';$('#list-caption').textContent=title[2];render()});
function openEditor(id){editing=id;$('#lead-form').reset();const l=leads.find(l=>l.id===id);if(l)Object.entries(l).forEach(([k,v])=>{const el=$('#lead-form').elements.namedItem(k);if(el)el.value=v??''});$('#editor-title').textContent=l?'Detalhes do lead':'Nova oportunidade';$('#delete-lead').hidden=!l;$('#editor').showModal()}
$('#new-lead').onclick=()=>openEditor(null);$('#close-editor').onclick=()=>$('#editor').close();$('#results').onclick=e=>{const b=e.target.closest('[data-edit]');if(b)openEditor(b.dataset.edit)};$('#results').onchange=e=>{if(e.target.dataset.stage)persist(leads.map(l=>l.id===e.target.dataset.stage?{...l,status:e.target.value}:l))};
$('#lead-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.name=d.name.trim();if(!d.name)return;d.instagram=d.instagram.trim();if(d.instagram&&!/^https?:\/\//i.test(d.instagram))d.instagram='https://www.instagram.com/'+d.instagram.replace(/^@/,'').replace(/\/$/,'')+'/';const prior=leads.find(l=>l.id===editing);const l={...prior,...d,id:editing||crypto.randomUUID(),updatedAt:new Date().toISOString()};if(persist(editing?leads.map(x=>x.id===editing?l:x):[...leads,l])){$('#editor').close();toast('Lead salvo. Próximo passo: uma boa conversa.')}};
$('#delete-lead').onclick=()=>{if(confirm('Excluir este lead e suas anotações?')){if(persist(leads.filter(l=>l.id!==editing)))$('#editor').close()}};
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#backup').onclick=()=>download(JSON.stringify({version:1,exportedAt:new Date().toISOString(),leads},null,2),'prospect-backup-'+today()+'.json','application/json');
$('#restore').onclick=()=>$('#restore-input').click();$('#restore-input').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>15e6)throw Error('Backup muito grande. Limite de 15 MB.');const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.leads)||data.leads.length>20000||!data.leads.every(l=>typeof l.name==='string'&&l.name.trim()&&stages[l.status]&&(!l.followup||/^\d{4}-\d{2}-\d{2}$/.test(l.followup))))throw Error('Arquivo de backup inválido. Use um backup exportado pelo Prospect.');const clean=data.leads.map(l=>{const item={id:crypto.randomUUID(),status:l.status,followup:l.followup||'',notes:String(l.notes||'')};for(const f of fields)item[f.key]=String(l[f.key]??'');return item});if(confirm('Restaurar '+clean.length+' leads? Sua base atual será substituída. Baixe um backup antes, se necessário.')){if(persist(clean))toast('Backup restaurado.')}}catch(err){toast(err.message)}finally{e.target.value=''}};
$('#export').onclick=()=>{const header=['Nome / Clínica','Categoria','Bairro','Cidade','Endereço','Telefone','Instagram','E-mail','Site','Link no Google Maps','Nota (Google)','Nº de avaliações','Etapa','Próximo contato','Anotações'];const cell=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';download('\ufeff'+[header,...filtered().map(l=>[l.name,l.category,l.district,l.city,l.address,l.phone,l.instagram,l.email,l.website,l.maps,l.rating,l.reviews,stages[l.status],l.followup,l.notes])].map(r=>r.map(cell).join(';')).join('\r\n'),'prospect-leads-'+today()+'.csv','text/csv;charset=utf-8')};
$('#import').onclick=()=>$('#import-dialog').showModal();$('#close-import').onclick=()=>$('#import-dialog').close();$('#file-input').onchange=e=>loadFile(e.target.files[0]);const zone=$('#dropzone');zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag')};zone.ondragleave=()=>zone.classList.remove('drag');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('drag');loadFile(e.dataTransfer.files[0])};
async function loadFile(file){if(!file)return;$('#confirm-import').disabled=true;$('#mapping').innerHTML='';$('#import-summary').textContent='Lendo planilha…';try{if(file.size>10e6)throw Error('O arquivo excede 10 MB. Divida a planilha e tente novamente.');if(!/\.(xlsx|xls|csv)$/i.test(file.name))throw Error('Escolha um arquivo XLSX, XLS ou CSV.');workbook=XLSX.read(await file.arrayBuffer(),{type:'array',cellFormula:false,cellHTML:false,sheetRows:20002});$('#mapping').innerHTML=`<label>Aba da planilha<select id="sheet">${workbook.SheetNames.map((s,i)=>`<option value="${i}">${esc(s)}</option>`).join('')}</select></label><div id="column-mapping"></div>`;$('#sheet').onchange=mapSheet;mapSheet()}catch(err){$('#import-summary').textContent=err.message;toast('Não foi possível importar: '+err.message)}}
function mapSheet(){const sheet=workbook.Sheets[workbook.SheetNames[+$('#sheet').value]];if(sheet['!fullref']&&sheet['!fullref']!==sheet['!ref']){$('#column-mapping').innerHTML='<p>A aba ultrapassa o limite de leitura. Divida a planilha em arquivos menores.</p>';$('#confirm-import').disabled=true;$('#import-summary').textContent='Aba muito grande; nenhum dado importado.';return}const rows=XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:false});const headerIndex=rows.findIndex(r=>r.some(v=>fields.find(f=>f.key==='name').aliases.includes(normalize(v)))||r.filter(v=>String(v).trim()).length>=2);if(headerIndex<0){$('#column-mapping').innerHTML='<p>Esta aba não possui uma tabela com cabeçalhos.</p>';$('#confirm-import').disabled=true;$('#import-summary').textContent='Escolha outra aba.';return}const headers=rows[headerIndex];importRows=rows.slice(headerIndex+1).filter(r=>r.some(v=>String(v).trim()));mapping={};for(const f of fields)mapping[f.key]=headers.findIndex(h=>f.aliases.includes(normalize(h)));$('#column-mapping').innerHTML=fields.map(f=>`<label style="display:flex;justify-content:space-between;gap:10px;align-items:center;font-size:12px;margin:8px 0">${f.label}${f.key==='name'?' *':''}<select data-field="${f.key}" aria-label="Coluna ${f.label}" style="width:60%"><option value="-1">Não importar</option>${headers.map((h,i)=>`<option value="${i}" ${mapping[f.key]===i?'selected':''}>${esc(h||'Coluna '+(i+1))}</option>`).join('')}</select></label>`).join('')+'<div id="import-preview" class="import-preview"></div>';$('#column-mapping').onchange=e=>{if(e.target.dataset.field){mapping[e.target.dataset.field]=+e.target.value;previewImport()}};previewImport()}
function parsed(){return importRows.map(row=>{const l={};for(const f of fields)l[f.key]=mapping[f.key]>=0?String(row[mapping[f.key]]??'').trim():'';return l}).filter(l=>l.name)}
function previewImport(){const rows=parsed();$('#confirm-import').disabled=mapping.name<0||!rows.length||rows.length>20000;$('#import-summary').textContent=rows.length>20000?'Limite de 20.000 leads por importação.':`${rows.length} leads com nome • duplicados serão ignorados`;$('#import-preview').innerHTML='<strong>Prévia</strong><br>'+rows.slice(0,3).map(l=>`${esc(l.name)} · ${esc(l.phone||'Sem telefone')}`).join('<br>')}
function merge(rows){const keys=new Set(leads.map(dedupeKey));let count=0;const added=[];for(const row of rows){const key=dedupeKey(row);if(keys.has(key))continue;keys.add(key);added.push({...row,id:crypto.randomUUID(),status:'novo',notes:'',followup:'',createdAt:new Date().toISOString()});count++}return {next:[...leads,...added],count}}
$('#confirm-import').onclick=()=>{const {next,count}=merge(parsed());if(persist(next)){$('#import-dialog').close();toast(`${count} leads importados. ${parsed().length-count} duplicados ignorados.`)}};
try{const saved=localStorage.getItem('prospect-leads-v1');if(saved!==null){const data=JSON.parse(saved);if(!Array.isArray(data))throw Error();leads=data}else{const res=await fetch('initial-leads.json');if(res.ok){const rows=await res.json();const mapped=rows.map(row=>Object.fromEntries(fields.map(f=>[f.key,String(Object.entries(row).find(([k])=>f.aliases.includes(normalize(k)))?.[1]??'')])));const result=merge(mapped);if(!persist(result.next))leads=result.next}}}catch{toast('Não foi possível carregar os dados. Restaure um backup ou importe sua planilha.')}render();
